CREATE FUNCTION public.identity_evidence_is_referenced(_bucket text, _path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.creator_verifications v WHERE v.document_bucket = _bucket AND _path IN (v.id_front_path, v.id_back_path, v.selfie_path)); $$;
REVOKE ALL ON FUNCTION public.identity_evidence_is_referenced(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.identity_evidence_is_referenced(text,text) TO authenticated,service_role;
CREATE POLICY "Retain all referenced creator identity evidence" ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING (bucket_id NOT IN ('identity-documents','id-verifications','creator-2257-records') OR NOT public.identity_evidence_is_referenced(bucket_id,name));
CREATE POLICY "Prevent replacement of referenced creator identity evidence" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (bucket_id NOT IN ('identity-documents','id-verifications','creator-2257-records') OR NOT public.identity_evidence_is_referenced(bucket_id,name)) WITH CHECK (bucket_id NOT IN ('identity-documents','id-verifications','creator-2257-records') OR NOT public.identity_evidence_is_referenced(bucket_id,name));
CREATE FUNCTION public.preserve_content_review_history() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN RAISE EXCEPTION 'Content review history is immutable'; END; $$;
REVOKE ALL ON FUNCTION public.preserve_content_review_history() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER preserve_content_review_history BEFORE UPDATE OR DELETE ON public.content_review_events FOR EACH ROW EXECUTE FUNCTION public.preserve_content_review_history();
CREATE FUNCTION public.preserve_participant_consent_record() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Participant consent records must be retained'; END IF; IF NEW.id IS DISTINCT FROM OLD.id OR NEW.manifest_id IS DISTINCT FROM OLD.manifest_id OR NEW.participant_id IS DISTINCT FROM OLD.participant_id OR NEW.signed_name IS DISTINCT FROM OLD.signed_name OR NEW.consent_text IS DISTINCT FROM OLD.consent_text OR NEW.release_path IS DISTINCT FROM OLD.release_path OR NEW.consented_at IS DISTINCT FROM OLD.consented_at THEN RAISE EXCEPTION 'Signed participant consent evidence is immutable'; END IF; IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN RAISE EXCEPTION 'Consent revocation cannot be erased or rewritten'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.preserve_participant_consent_record() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER preserve_participant_consent_record BEFORE UPDATE OR DELETE ON public.participant_consents FOR EACH ROW EXECUTE FUNCTION public.preserve_participant_consent_record();
COMMENT ON FUNCTION public.identity_evidence_is_referenced(text,text) IS 'Preserves referenced evidence against authenticated client deletion/replacement; not a timed retention schedule, backup or service-role object lock.';
COMMENT ON FUNCTION public.preserve_participant_consent_record() IS 'Retains signed consent and allows only first revocation; withdrawal does not erase the historical release.';